:root {
  --bg: #f5f6f8;
  --surface: #ffffff;
  --border: #e2e5ea;
  --text: #1c2430;
  --muted: #6b7688;
  --primary: #2f6bff;
  --primary-hover: #1f57e0;
  --danger: #d9463e;
  --shadow: 0 1px 3px rgba(20, 30, 50, 0.08), 0 6px 20px rgba(20, 30, 50, 0.06);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.45;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  max-width: 820px;
  margin: 0 auto;
}

.app-header h1 {
  font-size: 1.6rem;
  margin: 0;
}

.toolbar {
  display: flex;
  gap: 10px;
  align-items: center;
  max-width: 820px;
  margin: 0 auto;
  padding: 0 24px 12px;
}

.search-input {
  flex: 1;
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.95rem;
  background: var(--surface);
}

.tag-select {
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  font-size: 0.95rem;
}

.list-region {
  max-width: 820px;
  margin: 0 auto;
  padding: 0 24px 60px;
}

.bookmark-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.bookmark {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  box-shadow: var(--shadow);
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.bookmark-main {
  min-width: 0;
  flex: 1;
}

.bookmark-title {
  font-weight: 600;
  font-size: 1.02rem;
  text-decoration: none;
  color: var(--text);
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookmark-title:hover {
  color: var(--primary);
}

.bookmark-url {
  display: block;
  color: var(--muted);
  font-size: 0.85rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.bookmark-notes {
  margin: 6px 0 0;
  font-size: 0.9rem;
  color: #45505f;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.tag-row {
  margin-top: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  font-size: 0.75rem;
  background: #eef2ff;
  color: #3654c9;
  padding: 2px 8px;
  border-radius: 999px;
}

.bookmark-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
