test('duplicate address is warned (409), then savable with confirm (201) — FR-010', async () => {
  const first = await req(ctx.base, '/api/bookmarks', {
    method: 'POST',
    body: JSON.stringify({ url: 'example.com/dup', title: 'One' }),
